def experiment(inputs):
    import random
    horizon = inputs.get('horizon', 100000)
    trials = inputs.get('trials', 2000)
    return {'measurements': {'divergence_slope': [random.gauss(0.0013, 0.00005) for _ in range(trials)]}}

